import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Texture load (async, but function returns synchronously)
  let textureDispose = null;
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    textureDispose = () => tex.dispose();

    // Atlas source rect is full image (512x320)
    const aspect = 512 / 320;
    const geo = new PlaneGeometry(1.6, 1.6 / aspect); // width 1.6, height preserves aspect
    const mat = new MeshBasicNodeMaterial({ map: tex });
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, 0);
    group.add(mesh);
  });

  // Text overlay (synchronous)
  const text = ctx.fontAtlas.createText('Journal', {
    fontSize: 0.62,          // hero scale from design tokens
    color: '#e8ecf2',        // paper
    align: 'center'
  });
  text.position.set(0, 0, 0.01); // slight z offset to avoid z-fighting
  group.add(text);

  // Billboarding via update handler (called each frame by the adapter)
  group.userData.handlers = {
    update: (camera) => {
      group.lookAt(camera.position);
    }
  };

  // Cleanup – dispose resources and kill any GSAP timelines (none here)
  group.userData.cleanup = () => {
    if (textureDispose) textureDispose();
    // Dispose text geometry / materials (traversal)
    text.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material?.dispose();
        }
      }
      // fontAtlas text may have textures inside material
    });
  };

  return group;
}
